// NewSelect creates a new select widget with the set list of options and changes handler
func NewSelect(options []string, changed func(string)) *Select {
	s := &Select{
		OnChanged:   changed,
		Options:     options,
		PlaceHolder: defaultPlaceHolder,
	}
	s.ExtendBaseWidget(s)
	return s
}

// NewAllStrings creates a new select widget pre-populated with all the provided string options.
// This is a convenience constructor that sets up a Select with options and a change handler.
//
// Since: 2.2
func NewAllStrings(options []string, changed func(string)) *Select {
	return NewSelect(options, changed)
}

